insert into public.agents (id, name, title, bio, languages) values
  ('9b711e49-06c7-58e8-9d0a-3598d8e09d65', 'Aanya Mehta', 'Senior Advisor · Ahmedabad', 'Aanya has spent a decade working alongside architects and families in western India, with a particular eye for courtyard houses and modernist homes.', array['English', 'Hindi', 'Gujarati']::text[]),
  ('44e14ca5-6e41-5ee4-9627-c63f8ff0b874', 'Meera Kapoor', 'Advisor · Mumbai', 'Meera specializes in Mumbai''s coastal neighborhoods, from Bandra''s hillside lanes to the sea-facing homes of Juhu.', array['English', 'Hindi', 'Marathi']::text[]),
  ('301bfe15-b038-56d7-ba10-c85a0a24ea86', 'Kabir Rao', 'Advisor · Bengaluru & Pune', 'Kabir works with buyers relocating to Bengaluru and Pune, and with weekend-home seekers in the hills around both cities.', array['English', 'Hindi', 'Kannada', 'Marathi']::text[]),
  ('5922d2a7-20c5-5ded-a418-cdaff035469b', 'Ira Fernandes', 'Advisor · Goa', 'Born in Saligao, Ira knows North Goa village by village — and which houses stay cool through May.', array['English', 'Konkani', 'Hindi', 'Portuguese']::text[]),
  ('1c356268-6d65-522b-a86e-caff4ba7a69a', 'Vikram Sethi', 'Principal Advisor · Delhi', 'Vikram advises on Delhi''s central colonies and farmhouse estates, with twenty years of experience in the city''s residential market.', array['English', 'Hindi', 'Punjabi']::text[])
