  ('a2952b2c-0b9e-5b61-a2cb-eb13fe1b7d68', 'pali-hill-penthouse', 'Pali Hill Penthouse', 'Terraces, treetops and a view to the sea', 'Set at the top of one of Bandra''s most sought-after hills, this penthouse looks over a canopy of old trees towards the sea. A sculptural timber staircase rises through the center of the home to a rooftop terrace with a lap pool and an outdoor kitchen.

The lower level is arranged for both entertaining and retreat: a generous living and dining room with a fireplace, a library, and four bedroom suites, each with a dressing room. Finishes are restrained — oak, lime plaster and bronze — allowing the light and the view to do the work.', 'mumbai', 'Bandra West', 'Pali Hill, Bandra West, Mumbai', 19.0686, 72.8264, 240000000, 'penthouse'::public.property_type, 4, 5, 4600, 2022, 3, 'available'::public.property_status, true, '[{"category":"schools","name":"International school (IB curriculum)","distanceKm":3.2},{"category":"schools","name":"Senior secondary school","distanceKm":0.9},{"category":"schools","name":"Montessori pre-school","distanceKm":0.8},{"category":"healthcare","name":"Multi-speciality hospital","distanceKm":3.5},{"category":"healthcare","name":"24-hour pharmacy and clinic","distanceKm":1.7},{"category":"dining","name":"Neighborhood café","distanceKm":1.2},{"category":"dining","name":"Chef-led restaurant","distanceKm":1.7},{"category":"dining","name":"Bakery and deli","distanceKm":0.3},{"category":"shopping","name":"Gourmet grocer","distanceKm":1.7},{"category":"shopping","name":"Retail and design district","distanceKm":2.8},{"category":"transit","name":"Metro station","distanceKm":1.5},{"category":"transit","name":"International airport","distanceKm":4.7}]'::jsonb, '44e14ca5-6e41-5ee4-9627-c63f8ff0b874', '2026-09-10T10:00:00.000Z', '2026-09-10T10:00:00.000Z'),
  ('e2edb981-2ef1-59dc-9354-9242375bfde3', 'the-mill-loft', 'The Mill Loft', 'A converted mill apartment with five-meter ceilings', 'Within one of Lower Parel''s restored textile mills, The Mill Loft keeps the building''s best qualities — five-meter ceilings, tall steel windows and exposed timber beams — and adds a calm, contemporary interior.

